using ITKamianets.Engine.Net;
using UnityEngine;

var net = NetSession.Ensure();
net.GameId = "my-game";
net.GameVersion = Application.version;
net.MaxPlayers = 4;
net.LocalName = "Ada";

if (!net.HostDirect())
    Debug.LogError("Could not start the host.");

// On another machine: net.JoinDirect("192.168.1.5");
// The host validates gameplay requests and publishes authoritative state.
net.RosterChanged += () => Debug.Log(net.Players.Count + " players");
